mapper.select:
SELECT distinct COUNTER_ID AS id, COUNTER_NAME AS text FROM MST_COUNTER_PARTY
(COUNTER_ID LIKE CONCAT('%',CONCAT(#{search,jdbcType=VARCHAR},'%')) or COUNTER_NAME LIKE CONCAT('%',CONCAT(#{search,jdbcType=VARCHAR},'%')) )
AND COUNTER_ID = #{initValue,jdbcType=VARCHAR}

SELECT t.TRADE_ID tradeId,/**交易编号**/ t.F_TRADE_ID outTradeId, /*外部成交编号*/ NVL(deal1.BOOKSET_ID,deal2.BOOKSET_ID) prodId,/**金融产品代码**/ bok.BOOKSET_NAME prodName,/**金融产品名称**/ zc.FINPROD_ID assetId, /**资产代码**/ zc.FINPROD_ABBR assetName,/**资产名称**/ t.PS ps,/**交易方向**/ t.TRADE_DATE tradeDate,/**交易日**/ t.SETTLE_DATE settDate,/**交割日期**/ t.PRIN_AMT prinAmt, /**交易本金**/ t.COUNTER_ID counterId, /**交易对手**/ mst.COUNTER_NAME counterName, /**交易对手名称**/ t.INT_AMT intAmt,/**应收利息总额**/ t.CCY ccy,/**币种**/ t.TRADE_AMT settleAmt,/**结算金额**/ nvl(t.MY_ACCT_NO,stl.MY_ACCT_NO) myAcctNo,/**资金账户**/ d.GEN_TYPE dataSource /**数据来源**/ from TRD_PRODUCT_DEAL t LEFT JOIN TRD_PRODUCT_DEAL_ADD d on t.TRADE_ID = d.TRADE_ID LEFT JOIN FIN_PRODUCT zc on zc.finprod_id = t.finprod_id LEFT JOIN STL_ORDERS stl ON stl.TRADE_ID = t.TRADE_ID AND stl.BUSI_TYPE = #{busiType} AND STL.ORDER_TYPE NOT LIKE 'N%' LEFT JOIN BOK_DEAL_ACCOUNTING deal1 on deal1.BUSI_NO = t.TRADE_ID LEFT JOIN BOK_DEAL_ACCOUNTING deal2 ON stl.ORDER_ID = deal2.BUSI_NO LEFT JOIN BOK_BOOKSET bok on (bok.BOOKSET_ID = deal1.BOOKSET_ID) OR (bok.BOOKSET_ID = deal2.BOOKSET_ID) LEFT JOIN MST_COUNTER_PARTY mst on mst.COUNTER_ID = t.COUNTER_ID where t.BUSI_TYPE = #{busiType} and t.FINPROD_TYPE = #{finprodType}
and t.TRADE_ID like concat(concat('%',#{tradeId}),'%')
and NVL(deal1.BOOKSET_ID,deal2.BOOKSET_ID) IN
#{finprodId}
and zc.FINPROD_ID IN
#{assetId}
and t.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
and t.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
AND t.PS IN
#{ps}
AND d.GEN_TYPE IN
#{dataSource}
order by t.TRADE_ID desc
